for k in range(NumIndustries):
    for t in range(NumYears):
        stock_prev = Stock[k] if t == 0 else StockHold[k][t-1]
        model.addConstr(Produce[k][t] + stock_prev - StockHold[k][t] - quicksum(InputOne[j][k] * Produce[j][t] for j in range(NumIndustries)) - quicksum(InputTwo[j][k] * BuildCapa[j][t] for j in range(NumIndustries)) >= Demand[k], name=f"Demand_{k}_{t}")

for k in range(NumIndustries):
    for t in range(NumYears):
        if t <= 1:
            model.addConstr(Produce[k][t] <= Capacity[k], name=f"CapLimit_{k}_{t}")
        else:
            model.addConstr(Produce[k][t] <= Capacity[k] + quicksum(BuildCapa[k][tp] for tp in range(t-1)), name=f"CapLimit_{k}_{t}")

for k in range(NumIndustries):
    for t in range(NumYears):
        model.addConstr(Produce[k][t] >= 0, name=f"ProdNonNeg_{k}_{t}")
        model.addConstr(BuildCapa[k][t] >= 0, name=f"BuildNonNeg_{k}_{t}")
        model.addConstr(StockHold[k][t] >= 0, name=f"StockNonNeg_{k}_{t}")
